import React from 'react';

import { CopyIcon } from 'components';
import { LoadingDots } from 'components/UI';
import { usePngCopyFeedback } from 'hooks';

import {
  StyledPngCopyActions,
  StyledPngCopyButton,
  StyledPngCopyFeedback,
} from '../../TemplateSlide.styles';

const DEFAULT_FEEDBACK_ID = 'template-slide-png-copy-feedback';

export type TemplateSlidePngCopyActionProps = {
  slideRef: React.RefObject<HTMLElement>;
  feedbackId?: string;
  dataTestId?: string;
};

export const TemplateSlidePngCopyAction: React.FC<
  TemplateSlidePngCopyActionProps
> = ({ slideRef, feedbackId = DEFAULT_FEEDBACK_ID, dataTestId }) => {
  const { copyElementAsPng, feedbackMessage, isActionVisible, isExporting } =
    usePngCopyFeedback();

  return (
    <StyledPngCopyActions
      data-template-slide-png-copy-action="true"
      data-visible={isActionVisible ? 'true' : undefined}
      data-testid={dataTestId ?? 'png-copy-actions'}
    >
      <StyledPngCopyButton
        size="small"
        variant="secondary"
        elevated
        isLoading={isExporting}
        disabled={isExporting}
        aria-label="Copy slide as PNG"
        aria-busy={isExporting}
        aria-describedby={feedbackMessage ? feedbackId : undefined}
        onClick={() => copyElementAsPng(slideRef.current)}
      >
        {isExporting ? (
          <LoadingDots size="medium" color="mono" />
        ) : (
          <CopyIcon width={16} height={16} />
        )}
      </StyledPngCopyButton>
      {feedbackMessage ? (
        <StyledPngCopyFeedback
          id={feedbackId}
          role="status"
          aria-live="polite"
          data-testid="template-slide-png-copy-feedback"
        >
          {feedbackMessage}
        </StyledPngCopyFeedback>
      ) : null}
    </StyledPngCopyActions>
  );
};
